head.script:
scwin.onpageload = function () {

	let tabOpt = {
		label: "트리뷰",
		openAction: "select",
		closable: "true"
	};

	let opt = {

		frameMode: "wframe",
		alwaysDraw: false,
		src: "tabControl_treeView_virtual_WESF-21_(WSQ-5589)_sub1.xml"
	};

	tab_outline.addTab("tabControl1", tabOpt, opt)

	let tabOpt2 = {
		label: "캘린더",
		openAction: "new",
		closable: "true"
	};

	let opt2 = {

		frameMode: "wframe",
		alwaysDraw: false,
		src: "tabControl_treeView_virtual_WESF-21_(WSQ-5589)_sub2.xml"
	};

	tab_outline.addTab("tabControl2", tabOpt2, opt2)
};

	scwin.checkVal = function() {
		return WebSquare.wUnit.getDomById('tab_outline_contents_tabControl1_body_trv_menu_main_div').children.length == 3;
	}
	scwin.unitTest = function() {
		//Unit
		WebSquare.wUnit.start();
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tab_outline_tab_tabControl1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tab_outline_contents_tabControl1_body_trv_menu_node_1').children[0].click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tab_outline_tab_tabControl2').click()");
		WebSquare.wUnit.addCommand("pause", "500");	
		WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('tab_outline_tab_tabControl1').click()");
		WebSquare.wUnit.addCommand("pause", "500");
		WebSquare.wUnit.addCommand("assert", "scwin.checkVal()", "true");
		WebSquare.wUnit.addCommand("pause", "500");
		//Run test and stop
		WebSquare.wUnit.run();
		WebSquare.wUnit.stop();
	}
	scwin.unitTest();
